# transfer_rig — generated by tools/gen_model_py.py from the yaml
# cascade (2026-09-02 flip), then hand-edited since. The
# class IS the unit: family head → variants → quant cells;
# merged_defaults() walks the cascade. Parity pinned by
# tests/walls/suites/test_python_models.py + the http goldens.
#
# SSOT law: this file REPLACES model.yaml + variants/. A
# model.yaml reappearing next to it is a LOUD refusal.


from melite_models import  KnobRow,Model, Variant, Cell, LoraRow, LaneInputs, Genre, Quant


class TransferRig(Model):
    id = 'transfer_rig'
    genre = Genre.THREED
    label = 'Transfer Rig'
    description = 'Copy rig from source GLB onto target GLB via GPU KNN.'
    engine = 'comfyui'
    card = 'img-to-mesh'
    # the lane's ONE data fact: the SOMA-77 template skin the GPU
    # weight transfer interpolates from (no diffusion weights —
    # KimodoTransferWeights is bare torch KNN + barycentric interp)
    lane_inputs = LaneInputs(
        family='transfer_rig',
        model_path='somaskel77/skin_standard.npz',
    )
    # the CASCADE GATE (image-edit rework 2026-09-05) — this lane's
    # weight load is NOT a ComfyUI UNETLoader quant tier (audiocore
    # pack / native cpp / card-owned weightless flow / sam-or-npz
    # checkpoint). The cell ships NATIVE — the lane runs its single
    # native form; the lane's own engine owns whatever tier switching
    # the load has (NATIVE is the honest tier for "no UNETLoader
    # matrix").
    variants = (
        Variant(id='standard', label='Standard', route='transfer_rig', cells=(
            Cell(quant=Quant.NATIVE, label='Native', route='transfer_rig'),
        )),
    )

    # the img-to-mesh card surface for the rig-copy arm (row 3,
    # 2026-09-06) — two rows: the donor + target GLB path constants
    # (the anny CompositeCharacter pattern, same pack family).
    card_knobs = (
        KnobRow(card='rigged_glb', inject='PrimitiveString.0.value', kind='s'),
        KnobRow(card='target_glb', inject='PrimitiveString.1.value', kind='s'),
    )

    # Shared img-to-mesh form (2026-09-06) — see trellis2-native: the
    # rig arm rides the same Model dropdown as the two lift arms.
    form = 'form_img_to_mesh'

